inputs.default:
{
  "tools": [
    {
      "name": "get_reservation",
      "title": "Get a reservation",
      "description": "Look up one reservation by its ID.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "reservation_id": {
            "type": "string",
            "pattern": "^R[0-9]+$"
          }
        },
        "required": [
          "reservation_id"
        ],
        "additionalProperties": false
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "find_tables",
      "title": "Find open tables",
      "description": "List the open tables for a party on a date, optionally in one area.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "date": {
            "type": "string",
            "format": "date"
          },
          "party": {
            "type": "integer",
            "minimum": 1,
            "maximum": 20
          },
          "area": {
            "type": "string",
            "description": "Where to sit, such as terrace or bar."
          }
        },
        "required": [
          "date",
          "party"
        ],
        "additionalProperties": false
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "cancel_reservation",
      "title": "Cancel a reservation",
      "description": "Cancel a reservation the user holds.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "reservation_id": {
            "type": "string",
            "pattern": "^R[0-9]+$"
          },
          "reason": {
            "enum": [
              "change_of_plans",
              "illness",
              "other"
            ]
          }
        },
        "required": [
          "reservation_id",
          "reason"
        ],
        "additionalProperties": false
      },
      "annotations": {
        "destructiveHint": true
      }
    },
    {
      "name": "ask_concierge",
      "title": "Ask the concierge",
      "description": "Pass a question about a booking to the restaurant's concierge agent.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "reservation_id": {
            "type": "string",
            "pattern": "^R[0-9]+$"
          },
          "question": {
            "type": "string",
            "maxLength": 2000
          }
        },
        "required": [
          "reservation_id",
          "question"
        ],
        "additionalProperties": false
      }
    }
  ]
}

